import sys
from collections import defaultdict

def main():
    n, t = map(int, sys.stdin.read().split())
    dp = defaultdict(int)
    for a in range(1, 5):
        for b in range(1, 5):
            if a != b:
                dp[(a, b, 0, 0)] += 1
    for _ in range(n - 2):
        ndp = defaultdict(int)
        for (a, b, h, v), cnt in dp.items():
            for c in range(1, 5):
                if c == b:
                    continue
                nh, nv = h, v
                if a < b > c:
                    nh += 1
                elif a > b < c:
                    nv += 1
                if nh > 10 or nv > 10:
                    continue
                ndp[(b, c, nh, nv)] += cnt
        dp = ndp
    ans = 0
    for (a, b, h, v), cnt in dp.items():
        if h == t and v == t - 1:
            ans += cnt
    print(ans)

main()
